import Foundation

/// The guide words of one library stretch or warm-up move (since 2.0).
public struct StretchGuide: Hashable, Sendable {
    public let note: String
    public let steps: [String]
    public let feel: String
    public let careful: String
    init(_ note: String, _ steps: [String], _ feel: String, _ careful: String) {
        self.note = note; self.steps = steps; self.feel = feel; self.careful = careful
    }
}

extension StretchLibrary {
    public static func guide(_ id: String) -> StretchGuide? { guides[id] }

    /// The 37 move names of the ready-made lists (StretchCatalog) and the library stretch each one is.
    /// A name with no match is not in this map; `alias(for:)` gives nil and he keeps it as his own stretch.
    public static let aliases: [String: String] = [
        "chest in a doorway": "chest-door", "shoulder across the body": "shoulder-cross",
        "hip flexor lunge": "hip-flexor", "hamstring": "hamstring-seated", "thigh, standing": "quad-standing",
        "child's pose": "childs-pose", "calf against the wall": "calf-wall", "seated hamstring reach": "hamstring-seated",
        "figure-four on the back": "figure-four", "butterfly": "butterfly", "triceps overhead": "triceps-overhead",
        "biceps on the wall": "biceps-wall", "lat stretch on a rack": "lat-bar", "wrist and forearm": "wrist-forearm",
        "knees to chest": "knee-chest", "lying spinal twist": "spine-twist", "cat and cow": "cat-cow",
        "chair glute stretch": "glute-seated", "neck side tilt": "neck-side", "thread the needle": "thread-needle",
        "standing forward fold": "forward-fold", "standing side bend": "side-bend", "calf on a step": "calf-wall",
        "bent-knee calf stretch": "calf-bent", "quad stretch holding a rail": "quad-standing",
        "standing hip flexor tuck": "hip-flexor", "hamstring on a bench": "hamstring-seated",
        "standing outer-hip lean": "side-leg-cross",
        // No library match (kept as his own): Deep squat hold, Hands clasped behind the back,
        // Cross-legged forward reach, Happy baby, Neck diagonal, Chin tuck, Shoulder rolls,
        // Shoulder blade squeeze, Arms-wide chest opener.
    ]

    /// The library id for an old move name; nil when none.
    public static func alias(for oldName: String) -> String? {
        aliases[oldName.trimmingCharacters(in: .whitespaces).lowercased()]
    }

